"""Descriptive within-instrument continuity; no statistical hypothesis test."""
from pathlib import Path
import pandas as pd,json
P=Path(__file__).parent;O=P/'main_exhibits';out=[]
def read(f):return pd.read_csv(P/f,keep_default_na=False)
e=read('enel/green_2019_issue_pool_continuity.csv')
for r in e.itertuples():
 out.append(dict(issuer='Enel',instrument='2019 green UoP issue only',from_year=r.from_report_year,to_year=r.to_report_year,comparison=r.comparison,opening_report_lines=r.old_reported_project_lines,closing_report_lines=r.new_reported_project_lines,retained_lines=r.retained_reported_lines,entered_lines=r.entered_reported_lines,exited_lines=r.exited_reported_lines,report_line_retention=r.retained_reported_lines/r.old_reported_project_lines,allocation_overlap_lower=r.identity_overlap_share_lower,allocation_overlap_upper=r.identity_overlap_share_upper,allocation_overlap_report_line=r.allocation_overlap_share_of_old_line_sum,currency='EUR',denominator_old_allocation_stock=r.old_sum_rounded_line_allocations_EUR_m,amount_basis='Rounded line allocations; min(old,new) over common identities; hydro aggregate bounded',source_table='enel/green_2019_issue_pool_continuity.csv',qualification=r.boundary))
ib=read('iberdrola/history_2019_2024/matched_green_hybrid_projects_2019_2024.csv')
for start,end,kind in [(y,y+1,'adjacent') for y in range(2019,2024)]+[(2019,2024,'endpoint')]:
 a=set(ib[ib.report_year==start].project_standardised);b=set(ib[ib.report_year==end].project_standardised)
 out.append(dict(issuer='Iberdrola',instrument='XS1890845875',from_year=start,to_year=end,comparison=kind,opening_report_lines=len(a),closing_report_lines=len(b),retained_lines=len(a&b),entered_lines=len(b-a),exited_lines=len(a-b),report_line_retention=len(a&b)/len(a),allocation_overlap_lower='',allocation_overlap_upper='',allocation_overlap_report_line='',currency='EUR',denominator_old_allocation_stock=800,amount_basis='Instrument total only; project monetary allocation not disclosed',source_table='iberdrola/history_2019_2024/matched_green_hybrid_projects_2019_2024.csv',qualification='Same two named projects and EUR800m instrument stock; this does not prove constant project weights or expenditure identity. Monetary overlap not calculable.'))
s=read('sse/fixed_cohort_bond_project_links.csv');s=s[s.bond_group=='GB5'];a=s[s.report_year==2023].set_index('project_id');b=s[s.report_year==2024].set_index('project_id');old=pd.to_numeric(a.allocation_stock_gbp_m);new=pd.to_numeric(b.allocation_stock_gbp_m);overlap=sum(min(old[k],new[k]) for k in old.index.intersection(new.index))/old.sum()
out.append(dict(issuer='SSE',instrument='GB5 / XS2510903862',from_year=2023,to_year=2024,comparison='adjacent',opening_report_lines=len(a),closing_report_lines=len(b),retained_lines=len(a.index.intersection(b.index)),entered_lines=len(b.index.difference(a.index)),exited_lines=len(a.index.difference(b.index)),report_line_retention=1,allocation_overlap_lower=overlap,allocation_overlap_upper=overlap,allocation_overlap_report_line=overlap,currency='GBP',denominator_old_allocation_stock=old.sum(),amount_basis='Reported project allocation stocks; min(old,new) overlap',source_table='sse/fixed_cohort_bond_project_links.csv',qualification='Only two observed report snapshots; no earlier stability inferred. GB6 is excluded. Financial refinancing and project operation remain distinct.'))
d=pd.DataFrame(out)
# Full weighted overlap is not a main estimand when unique project money is incomplete.
d=d.drop(columns=['allocation_overlap_lower','allocation_overlap_upper','allocation_overlap_report_line'])
d['disclosed_reassignment_amount']='';d['verified_reassignment_denominator']='';d['disclosed_reassignment_share']=''
d.loc[(d.issuer=='Enel')&(d.from_year==2022)&(d.to_year==2023),'disclosed_reassignment_amount']=156.86
mask=(d.issuer=='Enel')&(d.from_year==2022)&(d.to_year==2023)
d.loc[mask,'verified_reassignment_denominator']=985.6
d.loc[mask,'disclosed_reassignment_share']=156.86/985.6
d['reassignment_denominator_basis']=''
d.loc[mask,'reassignment_denominator_basis']='Original 2019 issue allocated stock; 2019 report PDF6 summary (printed4), EUR985.6m. Not precise 2023 stock.'
d.loc[d.issuer=='Enel','qualification']=d.loc[d.issuer=='Enel','qualification']+' Counts are report entries; one entry aggregates eight unnamed hydro projects. Full monetary composition distance is not estimated.'
d.to_csv(O/'appendix_pool_continuity.csv',index=False)
checks={'rows':len(d),'retention_within_0_1':bool(d.report_line_retention.between(0,1).all()),'iberdrola_money_overlap_not_invented':bool((d[d.issuer=='Iberdrola'].disclosed_reassignment_share=='').all()),'sse_one_comparison':int((d.issuer=='SSE').sum())==1}
(O/'pool_continuity_validation.json').write_text(json.dumps(checks,indent=2))
(O/'POOL_CONTINUITY_METHOD.txt').write_text('Within-instrument classification and continuity check\n\nRetain issuer, instrument, report vintage and project identity. Report-line retention = common prior/current IDs divided by prior IDs. Monetary overlap and full composition distance are not estimated in the appendix data table because uniquely mapped project-money coverage is incomplete. Unmatched rows are not additional finance by definition. This is descriptive accounting, not a causal or statistical significance test.\n\nEnel: one Italian hydro line contains eight unnamed projects. Counts refer to reporting entries; the grouped hydro entry is not a unique plant. Auxiliary source bounds are excluded from the continuity analysis. Rounded project sums differ from printed totals by EUR1m in2023/2024. The exact2023 reassignment disclosure156.86m for the2019 issue is separate from rounded line arithmetic. Its15.91518% ratio uses the original2019 EUR985.6m allocated-stock base verified in2019 report PDF6 (printed4), not an asserted precise2023 stock. This is an identified minimum disclosed change, not exhaustive turnover. Combined2018+2019 reassignment229.60m must not be used as the2019-issue numerator.\n\nIberdrola: two named projects are stable across six reports and instrument allocation stays EUR800m. Project money is unavailable, so monetary-overlap cells stay blank. SSE: three GB5 project stocks are unchanged across2023/2024, with GBP543.9m denominator. GB6 and earlier unobserved snapshots are excluded. These stable reported observations establish continuity only in the dimensions observed. They do not establish unchanged ownership or constitute a fully verified physical-continuity benchmark.\n')
print(checks)
